import React, { useState } from 'react';
import './App.css';
import Navigation from './components/Navigation';
import TaskForm from './components/TaskForm';
import TaskList from './components/TaskList';
import SearchBar from './components/SearchBar';

function App() {
  const [tasks, setTasks] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');

  const addTask = (taskText) => {
    if (taskText.trim() !== '') {
      const newTask = {
        id: Date.now(),
        text: taskText,
        completed: false
      };
      setTasks([...tasks, newTask]);
    }
  };

  const toggleTask = (taskId) => {
    setTasks(tasks.map(task =>
      task.id === taskId ? { ...task, completed: !task.completed } : task
    ));
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter(task => task.id !== taskId));
  };

  const loadExampleTasks = () => {
    const baseId = Date.now();
    const exampleTasks = [
      { id: baseId + 1, text: 'Przykładowe zadanie 1', completed: false },
      { id: baseId + 2, text: 'Przykładowe zadanie 2', completed: false },
      { id: baseId + 3, text: 'Przykładowe zadanie 3', completed: false }
    ];
    setTasks([...tasks, ...exampleTasks]);
  };

  const filteredTasks = tasks.filter(task =>
    task.text.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="App">
      <Navigation />
      <div className="main-content">
        <h1 className="main-title">Lista zadań</h1>
        
        <TaskForm onAddTask={addTask} onLoadExamples={loadExampleTasks} />
        
        <SearchBar searchTerm={searchTerm} onSearchChange={setSearchTerm} />
        
        <TaskList
          tasks={filteredTasks}
          onToggleTask={toggleTask}
          onDeleteTask={deleteTask}
        />
      </div>
    </div>
  );
}

export default App;
